1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
4	  rune: 25,
5	  moonstone: 25,
6	};
7	const MAIN_ITEM_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
14	  ...MAIN_ITEM_BASE_PREMIUM_BY_TYPE,
15	  ...COMPONENT_BASE_PREMIUM_BY_TYPE,
16	};
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	const CURSED_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
22	const LOYALTY_MINIMUM_YEARS = 2;
23	const LOYALTY_DISCOUNT_RATE = 0.2;
24	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
25	const DEDUCTIBLE = 100;
26	const CAP_MULTIPLIER = 2;
27	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
28	const HALF_REIMBURSEMENT_RATE = 0.5;
29	const FULL_REIMBURSEMENT_RATE = 1;
30	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
31	  sword: 1000,
32	  amulet: 600,
33	  rune: 250,
34	};
35	
36	type Item = {
37	  type: string;
38	  material?: string;
39	  enchantment?: number;
40	  cursed?: boolean;
41	};
42	
43	type Damage = {
44	  itemType: string;
45	  amount: number;
46	};
47	
48	type Incident = {
49	  cause: string;
50	  damages: Damage[];
51	};
52	
53	type Step = {
54	  op: string;
55	  items?: Item[];
56	  policy?: number;
57	  incident?: Incident;
58	};
59	
60	type Scenario = {
61	  customer: { yearsWithMHPCO: number };
62	  steps: Step[];
63	};
64	
65	type QuoteResult = {
66	  premium: number;
67	};
68	
69	type ClaimResult = {
70	  payout: number;
71	  remainingCap: number;
72	};
73	
74	type StepResult = QuoteResult | ClaimResult;
75	
76	type ScenarioOutput = {
77	  results: StepResult[];
78	};
79	
80	const isComponent = (item: Item): boolean =>
81	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
82	
83	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
84	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
85	  sameTypeItems.every(isComponent);
86	
87	const groupByType = (items: Item[]): Item[][] => {
88	  const groups = new Map<string, Item[]>();
89	  for (const item of items) {
90	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
91	  }
92	  return [...groups.values()];
93	};
94	
95	const basePremiumForItem = (item: Item): number =>
96	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
97	
98	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
99	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
100	  return sameTypeItems.reduce(
101	    (total, item) => total + basePremiumForItem(item),
102	    0,
103	  );
104	};
105	
106	const basePremiumForItems = (items: Item[]): number =>
107	  groupByType(items).reduce(
108	    (total, group) => total + basePremiumForGroup(group),
109	    0,
110	  );
111	
112	const amountAtRate = (
113	  basePremium: number,
114	  rate: number,
115	  applies?: boolean,
116	): number => (applies ? basePremium * rate : 0);
117	
118	const cursedSurcharge = (item: Item): number =>
119	  amountAtRate(basePremiumForItem(item), CURSED_SURCHARGE_RATE, item.cursed);
120	
121	const enchantmentLevelOf = (item: Item | undefined): number =>
122	  item?.enchantment ?? 0;
123	
124	const hasHighEnchantment = (item: Item): boolean =>
125	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
126	
127	const highEnchantmentSurcharge = (item: Item): number =>
128	  amountAtRate(
129	    basePremiumForItem(item),
130	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
131	    hasHighEnchantment(item),
132	  );
133	
134	const totalItemSurcharges = (items: Item[]): number =>
135	  items.reduce(
136	    (total, item) =>
137	      total + cursedSurcharge(item) + highEnchantmentSurcharge(item),
138	    0,
139	  );
140	
141	const firstInsuranceSurcharge = (basePremium: number): number =>
142	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
143	
144	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
145	  yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS;
146	
147	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
148	  amountAtRate(
149	    basePremium,
150	    LOYALTY_DISCOUNT_RATE,
151	    isLoyalCustomer(yearsWithMHPCO),
152	  );
153	
154	const followUpDiscount = (basePremium: number, isFollowUp: boolean): number =>
155	  amountAtRate(basePremium, FOLLOW_UP_DISCOUNT_RATE, isFollowUp);
156	
157	const premiumBeforeProcessingFee = (
158	  items: Item[],
159	  yearsWithMHPCO: number,
160	  isFollowUp: boolean,
161	): number => {
162	  const basePremium = basePremiumForItems(items);
163	  return (
164	    basePremium +
165	    totalItemSurcharges(items) +
166	    firstInsuranceSurcharge(basePremium) -
167	    loyaltyDiscount(basePremium, yearsWithMHPCO) -
168	    followUpDiscount(basePremium, isFollowUp)
169	  );
170	};
171	
172	const isFollowUpQuote = (stepIndex: number): boolean => stepIndex > 0;
173	
174	const isClaimStep = (step: Step): boolean => step.op === "claim";
175	
176	const insuranceSumForItems = (items: Item[]): number =>
177	  items.reduce(
178	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
179	    0,
180	  );
181	
182	const capForItems = (items: Item[]): number =>
183	  insuranceSumForItems(items) * CAP_MULTIPLIER;
184	
185	const damagedItemFor = (
186	  damage: Damage,
187	  policyItems: Item[],
188	): Item | undefined =>
189	  policyItems.find((item) => item.type === damage.itemType);
190	
191	const reimbursementRateFor = (item: Item | undefined): number =>
192	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
193	    ? HALF_REIMBURSEMENT_RATE
194	    : FULL_REIMBURSEMENT_RATE;
195	
196	const payoutForDamage = (damage: Damage, policyItems: Item[]): number =>
197	  damage.amount * reimbursementRateFor(damagedItemFor(damage, policyItems)) -
198	  DEDUCTIBLE;
199	
200	const totalPayoutForDamages = (damages: Damage[], policyItems: Item[]): number =>
201	  damages.reduce(
202	    (total, damage) => total + payoutForDamage(damage, policyItems),
203	    0,
204	  );
205	
206	const policyIndexOf = (step: Step): number => step.policy ?? 0;
207	
208	const policyItemsAt = (policyIndex: number, steps: Step[]): Item[] =>
209	  steps[policyIndex].items ?? [];
210	
211	const damagesFor = (step: Step): Damage[] => step.incident?.damages ?? [];
212	
213	const claimResultFor = (
214	  step: Step,
215	  steps: Step[],
216	  remainingCapByPolicy: Map<number, number>,
217	): ClaimResult => {
218	  const policyIndex = policyIndexOf(step);
219	  const policyItems = policyItemsAt(policyIndex, steps);
220	  const availableCap =
221	    remainingCapByPolicy.get(policyIndex) ?? capForItems(policyItems);
222	  const payoutBeforeCap = Math.floor(
223	    totalPayoutForDamages(damagesFor(step), policyItems),
224	  );
225	  const payout = Math.min(payoutBeforeCap, availableCap);
226	  const remainingCap = availableCap - payout;
227	  remainingCapByPolicy.set(policyIndex, remainingCap);
228	  return { payout, remainingCap };
229	};
230	
231	const quoteResultFor = (
232	  step: Step,
233	  yearsWithMHPCO: number,
234	  stepIndex: number,
235	): QuoteResult => ({
236	  premium: Math.ceil(
237	    premiumBeforeProcessingFee(
238	      step.items ?? [],
239	      yearsWithMHPCO,
240	      isFollowUpQuote(stepIndex),
241	    ) + PROCESSING_FEE,
242	  ),
243	});
244	
245	export const runScenario = (scenario: Scenario): ScenarioOutput => {
246	  const remainingCapByPolicy = new Map<number, number>();
247	  return {
248	    results: scenario.steps.map((step, stepIndex) =>
249	      isClaimStep(step)
250	        ? claimResultFor(step, scenario.steps, remainingCapByPolicy)
251	        : quoteResultFor(step, scenario.customer.yearsWithMHPCO, stepIndex),
252	    ),
253	  };
254	};
